	c1 = c1.SetElem(1, archsimd.LoadInt32x4Array((*[4]int32)(c[4:8])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64().GetElem(0))
	c2 := c1.ToBits().ReshapeToUint16s().BitsToInt16()
	c3 := archsimd.LoadInt32x4Array((*[4]int32)(c[16:20])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64()
	c3 = c3.SetElem(1, archsimd.LoadInt32x4Array((*[4]int32)(c[20:24])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64().GetElem(0))
