	r10h := w12.MulAdd(k13, bias)
	r10 := r10l.ToBits().ReshapeToUint16s().ConcatOdd(r10h.ToBits().ReshapeToUint16s()).BitsToInt16()
	k15 := archsimd.LoadInt32x4Array(&t.p2896)
	r14l := w11.MulAdd(k15, bias)
	r14h := w12.MulAdd(k15, bias)
	r14 := r14l.ToBits().ReshapeToUint16s().ConcatOdd(r14h.ToBits().ReshapeToUint16s()).BitsToInt16()
	w17 := c6.ExtendLo4ToInt32()
	w18 := c6.HiToLo().ExtendLo4ToInt32()
	k19 := archsimd.LoadInt32x4Array(&t.p799)
	r16l := w17.MulAdd(k19, bias)
	r16h := w18.MulAdd(k19, bias)
