	c4 := c3.ToBits().ReshapeToUint16s().BitsToInt16()
	c5 := archsimd.LoadInt32x4Array((*[4]int32)(c[32:36])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64()
	c5 = c5.SetElem(1, archsimd.LoadInt32x4Array((*[4]int32)(c[36:40])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64().GetElem(0))
