	c7 = c7.SetElem(1, archsimd.LoadInt32x4Array((*[4]int32)(c[52:56])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64().GetElem(0))
	c8 := c7.ToBits().ReshapeToUint16s().BitsToInt16()
	c9 := archsimd.LoadInt32x4Array((*[4]int32)(c[64:68])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64()
	c9 = c9.SetElem(1, archsimd.LoadInt32x4Array((*[4]int32)(c[68:72])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64().GetElem(0))
	c10 := c9.ToBits().ReshapeToUint16s().BitsToInt16()
	c11 := archsimd.LoadInt32x4Array((*[4]int32)(c[80:84])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64()
	c11 = c11.SetElem(1, archsimd.LoadInt32x4Array((*[4]int32)(c[84:88])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64().GetElem(0))
	c12 := c11.ToBits().ReshapeToUint16s().BitsToInt16()
	c13 := archsimd.LoadInt32x4Array((*[4]int32)(c[96:100])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64()
