	r183l = w180.MulAdd(k185, r183l)
	r183h = w181.MulAdd(k185, r183h)
	r183 := r183l.ToBits().ReshapeToUint16s().ConcatOdd(r183h.ToBits().ReshapeToUint16s()).BitsToInt16()
	w187 := a172.ExtendLo4ToInt32()
	w188 := a172.HiToLo().ExtendLo4ToInt32()
	k189 := archsimd.LoadInt32x4Array(&t.p2896)
	r186l := w187.MulAdd(k189, bias)
	r186h := w188.MulAdd(k189, bias)
	w190 := a171.ExtendLo4ToInt32()
	w191 := a171.HiToLo().ExtendLo4ToInt32()
	k192 := archsimd.LoadInt32x4Array(&t.n2896)
	r186l = w190.MulAdd(k192, r186l)
