	a196 := a92.AddSaturated(a175)
	a197 := a93.AddSaturated(a174)
	a198 := a94.AddSaturated(r183)
	a199 := a95.AddSaturated(r193)
	a200 := a96.AddSaturated(r186)
	a201 := a97.AddSaturated(r176)
	a202 := a98.AddSaturated(a169)
	a203 := a99.AddSaturated(a168)
	a204 := a99.SubSaturated(a168)
	a205 := a98.SubSaturated(a169)
	a206 := a97.SubSaturated(r176)
	a207 := a96.SubSaturated(r186)
	a208 := a95.SubSaturated(r193)
	a209 := a94.SubSaturated(r183)
	a210 := a93.SubSaturated(a174)
	a211 := a92.SubSaturated(a175)
	s212 := a196.Shift(sh1).Average(zero)
	s213 := a197.Shift(sh1).Average(zero)
	s214 := a198.Shift(sh1).Average(zero)
	s215 := a199.Shift(sh1).Average(zero)
	s216 := a200.Shift(sh1).Average(zero)
	s217 := a201.Shift(sh1).Average(zero)
	s218 := a202.Shift(sh1).Average(zero)
	s219 := a203.Shift(sh1).Average(zero)
	x220a0 := s212.InterleaveLo(s213).ToBits().ReshapeToUint32s()
	x220a1 := s212.InterleaveHi(s213).ToBits().ReshapeToUint32s()
	x220a2 := s214.InterleaveLo(s215).ToBits().ReshapeToUint32s()
	x220a3 := s214.InterleaveHi(s215).ToBits().ReshapeToUint32s()
	x220a4 := s216.InterleaveLo(s217).ToBits().ReshapeToUint32s()
	x220a5 := s216.InterleaveHi(s217).ToBits().ReshapeToUint32s()
	x220a6 := s218.InterleaveLo(s219).ToBits().ReshapeToUint32s()
	x220a7 := s218.InterleaveHi(s219).ToBits().ReshapeToUint32s()
