	x220b1 := x220a0.InterleaveHi(x220a2).ReshapeToUint64s()
	x220b2 := x220a1.InterleaveLo(x220a3).ReshapeToUint64s()
	x220b3 := x220a1.InterleaveHi(x220a3).ReshapeToUint64s()
	x220b4 := x220a4.InterleaveLo(x220a6).ReshapeToUint64s()
	x220b5 := x220a4.InterleaveHi(x220a6).ReshapeToUint64s()
	x220b6 := x220a5.InterleaveLo(x220a7).ReshapeToUint64s()
	x220b7 := x220a5.InterleaveHi(x220a7).ReshapeToUint64s()
	x220t0 := x220b0.InterleaveLo(x220b4).ReshapeToUint16s().BitsToInt16()
	x220t1 := x220b0.InterleaveHi(x220b4).ReshapeToUint16s().BitsToInt16()
	x220t2 := x220b1.InterleaveLo(x220b5).ReshapeToUint16s().BitsToInt16()
	x220t3 := x220b1.InterleaveHi(x220b5).ReshapeToUint16s().BitsToInt16()
	x220t4 := x220b2.InterleaveLo(x220b6).ReshapeToUint16s().BitsToInt16()
	x220t5 := x220b2.InterleaveHi(x220b6).ReshapeToUint16s().BitsToInt16()
	x220t6 := x220b3.InterleaveLo(x220b7).ReshapeToUint16s().BitsToInt16()
