	w7 := m1.HiToLo().ExtendLo4ToInt32()
	k8 := archsimd.LoadInt32x4Array(&t.p2896)
	r5l := w6.MulAdd(k8, bias)
	r5h := w7.MulAdd(k8, bias)
	r5 := r5l.ToBits().ReshapeToUint16s().ConcatOdd(r5h.ToBits().ReshapeToUint16s()).BitsToInt16()
	k10 := archsimd.LoadInt32x4Array(&t.p2896)
	r9l := w6.MulAdd(k10, bias)
	r9h := w7.MulAdd(k10, bias)
	r9 := r9l.ToBits().ReshapeToUint16s().ConcatOdd(r9h.ToBits().ReshapeToUint16s()).BitsToInt16()
	w12 := m3.ExtendLo4ToInt32()
	w13 := m3.HiToLo().ExtendLo4ToInt32()
	k14 := archsimd.LoadInt32x4Array(&t.p799)
	r11l := w12.MulAdd(k14, bias)
	r11h := w13.MulAdd(k14, bias)
	r11 := r11l.ToBits().ReshapeToUint16s().ConcatOdd(r11h.ToBits().ReshapeToUint16s()).BitsToInt16()
	k16 := archsimd.LoadInt32x4Array(&t.p4017)
	r15l := w12.MulAdd(k16, bias)
	r15h := w13.MulAdd(k16, bias)
	r15 := r15l.ToBits().ReshapeToUint16s().ConcatOdd(r15h.ToBits().ReshapeToUint16s()).BitsToInt16()
	w18 := r15.ExtendLo4ToInt32()
	w19 := r15.HiToLo().ExtendLo4ToInt32()
	k20 := archsimd.LoadInt32x4Array(&t.p2896)
	r17l := w18.MulAdd(k20, bias)
	r17h := w19.MulAdd(k20, bias)
	w21 := r11.ExtendLo4ToInt32()
	w22 := r11.HiToLo().ExtendLo4ToInt32()
	k23 := archsimd.LoadInt32x4Array(&t.n2896)
	r17l = w21.MulAdd(k23, r17l)
	r17h = w22.MulAdd(k23, r17h)
	r17 := r17l.ToBits().ReshapeToUint16s().ConcatOdd(r17h.ToBits().ReshapeToUint16s()).BitsToInt16()
	k25 := archsimd.LoadInt32x4Array(&t.p2896)
	r24l := w18.MulAdd(k25, bias)
	r24h := w19.MulAdd(k25, bias)
	k26 := archsimd.LoadInt32x4Array(&t.p2896)
	r24l = w21.MulAdd(k26, r24l)
	r24h = w22.MulAdd(k26, r24h)
	r24 := r24l.ToBits().ReshapeToUint16s().ConcatOdd(r24h.ToBits().ReshapeToUint16s()).BitsToInt16()
