	w37 := m2.HiToLo().ExtendLo4ToInt32()
	k38 := archsimd.LoadInt32x4Array(&t.p401)
	r35l := w36.MulAdd(k38, bias)
	r35h := w37.MulAdd(k38, bias)
	r35 := r35l.ToBits().ReshapeToUint16s().ConcatOdd(r35h.ToBits().ReshapeToUint16s()).BitsToInt16()
	k40 := archsimd.LoadInt32x4Array(&t.p4076)
	r39l := w36.MulAdd(k40, bias)
	r39h := w37.MulAdd(k40, bias)
	r39 := r39l.ToBits().ReshapeToUint16s().ConcatOdd(r39h.ToBits().ReshapeToUint16s()).BitsToInt16()
	w42 := m4.ExtendLo4ToInt32()
	w43 := m4.HiToLo().ExtendLo4ToInt32()
	k44 := archsimd.LoadInt32x4Array(&t.n1189)
	r41l := w42.MulAdd(k44, bias)
	r41h := w43.MulAdd(k44, bias)
	r41 := r41l.ToBits().ReshapeToUint16s().ConcatOdd(r41h.ToBits().ReshapeToUint16s()).BitsToInt16()
	k46 := archsimd.LoadInt32x4Array(&t.p3920)
	r45l := w42.MulAdd(k46, bias)
	r45h := w43.MulAdd(k46, bias)
	r45 := r45l.ToBits().ReshapeToUint16s().ConcatOdd(r45h.ToBits().ReshapeToUint16s()).BitsToInt16()
	w48 := r39.ExtendLo4ToInt32()
	w49 := r39.HiToLo().ExtendLo4ToInt32()
	k50 := archsimd.LoadInt32x4Array(&t.p1567)
	r47l := w48.MulAdd(k50, bias)
	r47h := w49.MulAdd(k50, bias)
	w51 := r35.ExtendLo4ToInt32()
	w52 := r35.HiToLo().ExtendLo4ToInt32()
	k53 := archsimd.LoadInt32x4Array(&t.n3784)
	r47l = w51.MulAdd(k53, r47l)
	r47h = w52.MulAdd(k53, r47h)
	r47 := r47l.ToBits().ReshapeToUint16s().ConcatOdd(r47h.ToBits().ReshapeToUint16s()).BitsToInt16()
	k55 := archsimd.LoadInt32x4Array(&t.p3784)
	r54l := w48.MulAdd(k55, bias)
	r54h := w49.MulAdd(k55, bias)
	k56 := archsimd.LoadInt32x4Array(&t.p1567)
	r54l = w51.MulAdd(k56, r54l)
	r54h = w52.MulAdd(k56, r54h)
	r54 := r54l.ToBits().ReshapeToUint16s().ConcatOdd(r54h.ToBits().ReshapeToUint16s()).BitsToInt16()
	w58 := r45.ExtendLo4ToInt32()
	w59 := r45.HiToLo().ExtendLo4ToInt32()
	k60 := archsimd.LoadInt32x4Array(&t.n3784)
	r57l := w58.MulAdd(k60, bias)
	r57h := w59.MulAdd(k60, bias)
	w61 := r41.ExtendLo4ToInt32()
	w62 := r41.HiToLo().ExtendLo4ToInt32()
	k63 := archsimd.LoadInt32x4Array(&t.n1567)
	r57l = w61.MulAdd(k63, r57l)
	r57h = w62.MulAdd(k63, r57h)
	r57 := r57l.ToBits().ReshapeToUint16s().ConcatOdd(r57h.ToBits().ReshapeToUint16s()).BitsToInt16()
	k65 := archsimd.LoadInt32x4Array(&t.p1567)
	r64l := w58.MulAdd(k65, bias)
	r64h := w59.MulAdd(k65, bias)
	k66 := archsimd.LoadInt32x4Array(&t.n3784)
	r64l = w61.MulAdd(k66, r64l)
	r64h = w62.MulAdd(k66, r64h)
	r64 := r64l.ToBits().ReshapeToUint16s().ConcatOdd(r64h.ToBits().ReshapeToUint16s()).BitsToInt16()
	a67 := r35.AddSaturated(r41)
	a68 := r47.AddSaturated(r57)
	a69 := r47.SubSaturated(r57)
	a70 := r35.SubSaturated(r41)
	a71 := r39.SubSaturated(r45)
	a72 := r54.SubSaturated(r64)
	a73 := r54.AddSaturated(r64)
	a74 := r39.AddSaturated(r45)
	w76 := a72.ExtendLo4ToInt32()
	w77 := a72.HiToLo().ExtendLo4ToInt32()
	k78 := archsimd.LoadInt32x4Array(&t.p2896)
	r75l := w76.MulAdd(k78, bias)
	r75h := w77.MulAdd(k78, bias)
	w79 := a69.ExtendLo4ToInt32()
	w80 := a69.HiToLo().ExtendLo4ToInt32()
	k81 := archsimd.LoadInt32x4Array(&t.n2896)
	r75l = w79.MulAdd(k81, r75l)
	r75h = w80.MulAdd(k81, r75h)
	r75 := r75l.ToBits().ReshapeToUint16s().ConcatOdd(r75h.ToBits().ReshapeToUint16s()).BitsToInt16()
	k83 := archsimd.LoadInt32x4Array(&t.p2896)
	r82l := w76.MulAdd(k83, bias)
	r82h := w77.MulAdd(k83, bias)
	k84 := archsimd.LoadInt32x4Array(&t.p2896)
	r82l = w79.MulAdd(k84, r82l)
	r82h = w80.MulAdd(k84, r82h)
	r82 := r82l.ToBits().ReshapeToUint16s().ConcatOdd(r82h.ToBits().ReshapeToUint16s()).BitsToInt16()
	w86 := a71.ExtendLo4ToInt32()
	w87 := a71.HiToLo().ExtendLo4ToInt32()
	k88 := archsimd.LoadInt32x4Array(&t.p2896)
	r85l := w86.MulAdd(k88, bias)
	r85h := w87.MulAdd(k88, bias)
	w89 := a70.ExtendLo4ToInt32()
	w90 := a70.HiToLo().ExtendLo4ToInt32()
	k91 := archsimd.LoadInt32x4Array(&t.n2896)
	r85l = w89.MulAdd(k91, r85l)
	r85h = w90.MulAdd(k91, r85h)
	r85 := r85l.ToBits().ReshapeToUint16s().ConcatOdd(r85h.ToBits().ReshapeToUint16s()).BitsToInt16()
	k93 := archsimd.LoadInt32x4Array(&t.p2896)
	r92l := w86.MulAdd(k93, bias)
	r92h := w87.MulAdd(k93, bias)
	k94 := archsimd.LoadInt32x4Array(&t.p2896)
	r92l = w89.MulAdd(k94, r92l)
	r92h = w90.MulAdd(k94, r92h)
	r92 := r92l.ToBits().ReshapeToUint16s().ConcatOdd(r92h.ToBits().ReshapeToUint16s()).BitsToInt16()
	a95 := a27.AddSaturated(a74)
	a96 := a28.AddSaturated(a73)
	a97 := a29.AddSaturated(r82)
	a98 := a30.AddSaturated(r92)
	a99 := a31.AddSaturated(r85)
	a100 := a32.AddSaturated(r75)
	a101 := a33.AddSaturated(a68)
	a102 := a34.AddSaturated(a67)
	a103 := a34.SubSaturated(a67)
	a104 := a33.SubSaturated(a68)
	a105 := a32.SubSaturated(r75)
	a106 := a31.SubSaturated(r85)
	a107 := a30.SubSaturated(r92)
	a108 := a29.SubSaturated(r82)
	a109 := a28.SubSaturated(a73)
	a110 := a27.SubSaturated(a74)
	dl111, pl112 := len(d)-8, len(p)-16
