	w14 := c6.ExtendLo4ToInt32()
	w15 := c6.HiToLo().ExtendLo4ToInt32()
	k16 := archsimd.LoadInt32x4Array(&t.p2896)
	r10l = w14.MulAdd(k16, r10l)
	r10h = w15.MulAdd(k16, r10h)
	r10 := r10l.ToBits().ReshapeToUint16s().ConcatOdd(r10h.ToBits().ReshapeToUint16s()).BitsToInt16()
	k18 := archsimd.LoadInt32x4Array(&t.p2896)
	r17l := w11.MulAdd(k18, bias)
	r17h := w12.MulAdd(k18, bias)
	k19 := archsimd.LoadInt32x4Array(&t.n2896)
	r17l = w14.MulAdd(k19, r17l)
	r17h = w15.MulAdd(k19, r17h)
	r17 := r17l.ToBits().ReshapeToUint16s().ConcatOdd(r17h.ToBits().ReshapeToUint16s()).BitsToInt16()
