	w22 := c4.HiToLo().ExtendLo4ToInt32()
	k23 := archsimd.LoadInt32x4Array(&t.p1567)
	r20l := w21.MulAdd(k23, bias)
	r20h := w22.MulAdd(k23, bias)
	w24 := c8.ExtendLo4ToInt32()
	w25 := c8.HiToLo().ExtendLo4ToInt32()
	k26 := archsimd.LoadInt32x4Array(&t.n3784)
	r20l = w24.MulAdd(k26, r20l)
	r20h = w25.MulAdd(k26, r20h)
	r20 := r20l.ToBits().ReshapeToUint16s().ConcatOdd(r20h.ToBits().ReshapeToUint16s()).BitsToInt16()
	k28 := archsimd.LoadInt32x4Array(&t.p3784)
	r27l := w21.MulAdd(k28, bias)
