	// Column strip 0: columns 0..3.
	w37 := x34t0.ExtendLo4ToInt32()
	k38 := archsimd.LoadInt32x4Array(&t.p2896)
	r36l := w37.MulAdd(k38, bias)
	w39 := x34t4.ExtendLo4ToInt32()
	k40 := archsimd.LoadInt32x4Array(&t.p2896)
	r36l = w39.MulAdd(k40, r36l)
	r36 := r36l.ToBits().ReshapeToUint16s().ConcatOdd(r36l.ToBits().ReshapeToUint16s()).BitsToInt16()
	k42 := archsimd.LoadInt32x4Array(&t.p2896)
	r41l := w37.MulAdd(k42, bias)
	k43 := archsimd.LoadInt32x4Array(&t.n2896)
	r41l = w39.MulAdd(k43, r41l)
	r41 := r41l.ToBits().ReshapeToUint16s().ConcatOdd(r41l.ToBits().ReshapeToUint16s()).BitsToInt16()
	w45 := x34t2.ExtendLo4ToInt32()
	k46 := archsimd.LoadInt32x4Array(&t.p1567)
	r44l := w45.MulAdd(k46, bias)
	w47 := x34t6.ExtendLo4ToInt32()
	k48 := archsimd.LoadInt32x4Array(&t.n3784)
	r44l = w47.MulAdd(k48, r44l)
