	k50 := archsimd.LoadInt32x4Array(&t.p3784)
	r49l := w45.MulAdd(k50, bias)
	k51 := archsimd.LoadInt32x4Array(&t.p1567)
	r49l = w47.MulAdd(k51, r49l)
