	a54 := r41.SubSaturated(r44)
	a55 := r36.SubSaturated(r49)
	w57 := x34t1.ExtendLo4ToInt32()
	k58 := archsimd.LoadInt32x4Array(&t.p799)
	r56l := w57.MulAdd(k58, bias)
	w59 := x34t7.ExtendLo4ToInt32()
	k60 := archsimd.LoadInt32x4Array(&t.n4017)
	r56l = w59.MulAdd(k60, r56l)
