	w62 := x34t5.ExtendLo4ToInt32()
	k63 := archsimd.LoadInt32x4Array(&t.p3406)
	r61l := w62.MulAdd(k63, bias)
	w64 := x34t3.ExtendLo4ToInt32()
	k65 := archsimd.LoadInt32x4Array(&t.n2276)
