	r61 := r61l.ToBits().ReshapeToUint16s().ConcatOdd(r61l.ToBits().ReshapeToUint16s()).BitsToInt16()
	k67 := archsimd.LoadInt32x4Array(&t.p2276)
	r66l := w62.MulAdd(k67, bias)
	k68 := archsimd.LoadInt32x4Array(&t.p3406)
	r66l = w64.MulAdd(k68, r66l)
	r66 := r66l.ToBits().ReshapeToUint16s().ConcatOdd(r66l.ToBits().ReshapeToUint16s()).BitsToInt16()
	k70 := archsimd.LoadInt32x4Array(&t.p4017)
	r69l := w57.MulAdd(k70, bias)
	k71 := archsimd.LoadInt32x4Array(&t.p799)
	r69l = w59.MulAdd(k71, r69l)
