	a72 := r56.AddSaturated(r61)
	a73 := r56.SubSaturated(r61)
	a74 := r69.AddSaturated(r66)
	a75 := r69.SubSaturated(r66)
	w77 := a75.ExtendLo4ToInt32()
	k78 := archsimd.LoadInt32x4Array(&t.p2896)
	r76l := w77.MulAdd(k78, bias)
	w79 := a73.ExtendLo4ToInt32()
	k80 := archsimd.LoadInt32x4Array(&t.n2896)
	r76l = w79.MulAdd(k80, r76l)
	r76 := r76l.ToBits().ReshapeToUint16s().ConcatOdd(r76l.ToBits().ReshapeToUint16s()).BitsToInt16()
