	s113 := a85.Shift(sh3).Average(zero)
	p114 := pf.SetElem(0, uint32(pw97[0])|uint32(pw97[1])<<8|uint32(pw97[2])<<16|uint32(pw97[3])<<24).ReshapeToUint8s().ExtendLo8ToUint16().BitsToInt16()
	o115 := p114.Add(s113).SaturateToUint8().ReshapeToUint32s().GetElem(0)
	dw96[0], dw96[1], dw96[2], dw96[3] = byte(o115), byte(o115>>8), byte(o115>>16), byte(o115>>24)
	s116 := a86.Shift(sh3).Average(zero)
	p117 := pf.SetElem(0, uint32(pw99[0])|uint32(pw99[1])<<8|uint32(pw99[2])<<16|uint32(pw99[3])<<24).ReshapeToUint8s().ExtendLo8ToUint16().BitsToInt16()
	o118 := p117.Add(s116).SaturateToUint8().ReshapeToUint32s().GetElem(0)
	dw98[0], dw98[1], dw98[2], dw98[3] = byte(o118), byte(o118>>8), byte(o118>>16), byte(o118>>24)
	s119 := a87.Shift(sh3).Average(zero)
	p120 := pf.SetElem(0, uint32(pw101[0])|uint32(pw101[1])<<8|uint32(pw101[2])<<16|uint32(pw101[3])<<24).ReshapeToUint8s().ExtendLo8ToUint16().BitsToInt16()
	o121 := p120.Add(s119).SaturateToUint8().ReshapeToUint32s().GetElem(0)
	dw100[0], dw100[1], dw100[2], dw100[3] = byte(o121), byte(o121>>8), byte(o121>>16), byte(o121>>24)
	s122 := a88.Shift(sh3).Average(zero)
	p123 := pf.SetElem(0, uint32(pw103[0])|uint32(pw103[1])<<8|uint32(pw103[2])<<16|uint32(pw103[3])<<24).ReshapeToUint8s().ExtendLo8ToUint16().BitsToInt16()
	o124 := p123.Add(s122).SaturateToUint8().ReshapeToUint32s().GetElem(0)
	dw102[0], dw102[1], dw102[2], dw102[3] = byte(o124), byte(o124>>8), byte(o124>>16), byte(o124>>24)
	s125 := a89.Shift(sh3).Average(zero)
	p126 := pf.SetElem(0, uint32(pw105[0])|uint32(pw105[1])<<8|uint32(pw105[2])<<16|uint32(pw105[3])<<24).ReshapeToUint8s().ExtendLo8ToUint16().BitsToInt16()
	o127 := p126.Add(s125).SaturateToUint8().ReshapeToUint32s().GetElem(0)
	dw104[0], dw104[1], dw104[2], dw104[3] = byte(o127), byte(o127>>8), byte(o127>>16), byte(o127>>24)
	s128 := a90.Shift(sh3).Average(zero)
	p129 := pf.SetElem(0, uint32(pw107[0])|uint32(pw107[1])<<8|uint32(pw107[2])<<16|uint32(pw107[3])<<24).ReshapeToUint8s().ExtendLo8ToUint16().BitsToInt16()
	o130 := p129.Add(s128).SaturateToUint8().ReshapeToUint32s().GetElem(0)
