	p132 := pf.SetElem(0, uint32(pw109[0])|uint32(pw109[1])<<8|uint32(pw109[2])<<16|uint32(pw109[3])<<24).ReshapeToUint8s().ExtendLo8ToUint16().BitsToInt16()
	o133 := p132.Add(s131).SaturateToUint8().ReshapeToUint32s().GetElem(0)
	dw108[0], dw108[1], dw108[2], dw108[3] = byte(o133), byte(o133>>8), byte(o133>>16), byte(o133>>24)
