	c4 := c3.ToBits().ReshapeToUint16s().BitsToInt16()
	c5 := archsimd.LoadInt32x4Array((*[4]int32)(c[16:20])).Max(archsimd.LoadInt32x4Array(&t.rlo)).Min(archsimd.LoadInt32x4Array(&t.rhi)).MulAdd(archsimd.LoadInt32x4Array(&t.r181), archsimd.LoadInt32x4Array(&t.r128)).ShiftAllRight(8).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64()
	c5 = c5.SetElem(1, archsimd.LoadInt32x4Array((*[4]int32)(c[20:24])).Max(archsimd.LoadInt32x4Array(&t.rlo)).Min(archsimd.LoadInt32x4Array(&t.rhi)).MulAdd(archsimd.LoadInt32x4Array(&t.r181), archsimd.LoadInt32x4Array(&t.r128)).ShiftAllRight(8).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64().GetElem(0))
	c6 := c5.ToBits().ReshapeToUint16s().BitsToInt16()
	c7 := archsimd.LoadInt32x4Array((*[4]int32)(c[24:28])).Max(archsimd.LoadInt32x4Array(&t.rlo)).Min(archsimd.LoadInt32x4Array(&t.rhi)).MulAdd(archsimd.LoadInt32x4Array(&t.r181), archsimd.LoadInt32x4Array(&t.r128)).ShiftAllRight(8).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64()
	c7 = c7.SetElem(1, archsimd.LoadInt32x4Array((*[4]int32)(c[28:32])).Max(archsimd.LoadInt32x4Array(&t.rlo)).Min(archsimd.LoadInt32x4Array(&t.rhi)).MulAdd(archsimd.LoadInt32x4Array(&t.r181), archsimd.LoadInt32x4Array(&t.r128)).ShiftAllRight(8).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64().GetElem(0))
