	f26 = f26.SetElem(1, w22.MulAdd(k23, k24).ShiftAllRight(12).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64().GetElem(0))
	r25 := f26.ToBits().ReshapeToUint16s().BitsToInt16()
	w27 := c8.ExtendLo4ToInt32()
	w28 := c8.HiToLo().ExtendLo4ToInt32()
	k29 := archsimd.LoadInt32x4Array(&t.m5793)
	k30 := archsimd.LoadInt32x4Array(&t.b2048)
	f32 := w27.MulAdd(k29, k30).ShiftAllRight(12).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64()
	f32 = f32.SetElem(1, w28.MulAdd(k29, k30).ShiftAllRight(12).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64().GetElem(0))
	r31 := f32.ToBits().ReshapeToUint16s().BitsToInt16()
