	x33b1 := x33a0.InterleaveHi(x33a2).ReshapeToUint64s()
	x33b2 := x33a1.InterleaveLo(x33a3).ReshapeToUint64s()
	x33b3 := x33a1.InterleaveHi(x33a3).ReshapeToUint64s()
