	r30l := w31.MulAdd(k32, bias)
	w33 := c8.ExtendLo4ToInt32()
	k34 := archsimd.LoadInt32x4Array(&t.n4017)
	r30l = w33.MulAdd(k34, r30l)
	r30 := r30l.ToBits().ReshapeToUint16s().ConcatOdd(r30l.ToBits().ReshapeToUint16s()).BitsToInt16()
	w36 := c6.ExtendLo4ToInt32()
	k37 := archsimd.LoadInt32x4Array(&t.p3406)
	r35l := w36.MulAdd(k37, bias)
	w38 := c4.ExtendLo4ToInt32()
	k39 := archsimd.LoadInt32x4Array(&t.n2276)
	r35l = w38.MulAdd(k39, r35l)
	r35 := r35l.ToBits().ReshapeToUint16s().ConcatOdd(r35l.ToBits().ReshapeToUint16s()).BitsToInt16()
	k41 := archsimd.LoadInt32x4Array(&t.p2276)
	r40l := w36.MulAdd(k41, bias)
	k42 := archsimd.LoadInt32x4Array(&t.p3406)
	r40l = w38.MulAdd(k42, r40l)
	r40 := r40l.ToBits().ReshapeToUint16s().ConcatOdd(r40l.ToBits().ReshapeToUint16s()).BitsToInt16()
	k44 := archsimd.LoadInt32x4Array(&t.p4017)
	r43l := w31.MulAdd(k44, bias)
	k45 := archsimd.LoadInt32x4Array(&t.p799)
	r43l = w33.MulAdd(k45, r43l)
	r43 := r43l.ToBits().ReshapeToUint16s().ConcatOdd(r43l.ToBits().ReshapeToUint16s()).BitsToInt16()
	a46 := r30.AddSaturated(r35)
	a47 := r30.SubSaturated(r35)
	a48 := r43.AddSaturated(r40)
	a49 := r43.SubSaturated(r40)
	w51 := a49.ExtendLo4ToInt32()
	k52 := archsimd.LoadInt32x4Array(&t.p2896)
	r50l := w51.MulAdd(k52, bias)
	w53 := a47.ExtendLo4ToInt32()
	k54 := archsimd.LoadInt32x4Array(&t.n2896)
	r50l = w53.MulAdd(k54, r50l)
	r50 := r50l.ToBits().ReshapeToUint16s().ConcatOdd(r50l.ToBits().ReshapeToUint16s()).BitsToInt16()
	k56 := archsimd.LoadInt32x4Array(&t.p2896)
	r55l := w51.MulAdd(k56, bias)
	k57 := archsimd.LoadInt32x4Array(&t.p2896)
	r55l = w53.MulAdd(k57, r55l)
	r55 := r55l.ToBits().ReshapeToUint16s().ConcatOdd(r55l.ToBits().ReshapeToUint16s()).BitsToInt16()
	a58 := a26.AddSaturated(a48)
	a59 := a27.AddSaturated(r55)
