// itxGen4x16 runs the generated 4x16 kernel of type t and the network forms
// covering cols coded columns and rows coded rows; it reports false for a
// type without one and when a guard declines.
func itxGen4x16(c *[64]int32, d []byte, ds int, p []byte, ps int, t Type, cols, rows int) bool {
	switch t {
	case TypeDCTDCT:
		if rows <= 4 {
			return itxGen4x16DCTDCTC4R4(c, d, ds, p, ps)
		}
		return itxGen4x16DCTDCTC4R16(c, d, ds, p, ps)
	case TypeADSTDCT:
		return itxGen4x16ADSTDCTC4R16(c, d, ds, p, ps)
	case TypeDCTADST:
		return itxGen4x16DCTADSTC4R16(c, d, ds, p, ps)
	case TypeADSTADST:
		return itxGen4x16ADSTADSTC4R16(c, d, ds, p, ps)
	case TypeFlipADSTDCT:
		return itxGen4x16FlipDCTC4R16(c, d, ds, p, ps)
	case TypeDCTFlipADST:
		return itxGen4x16DCTFlipC4R16(c, d, ds, p, ps)
	case TypeFlipADSTFlipADST:
		return itxGen4x16FlipFlipC4R16(c, d, ds, p, ps)
	case TypeADSTFlipADST:
		return itxGen4x16ADSTFlipC4R16(c, d, ds, p, ps)
	case TypeFlipADSTADST:
		return itxGen4x16FlipADSTC4R16(c, d, ds, p, ps)
	case TypeVDCT:
		return itxGen4x16DCTIdenC4R16(c, d, ds, p, ps)
	case TypeHDCT:
		return itxGen4x16IdenDCTC4R16(c, d, ds, p, ps)
	}
	return false
}

