	x38b1 := x38a0.InterleaveHi(x38a2).ReshapeToUint64s()
	x38b2 := x38a1.InterleaveLo(x38a3).ReshapeToUint64s()
	x38b3 := x38a1.InterleaveHi(x38a3).ReshapeToUint64s()
	x38t0 := x38b0.InterleaveLo(zero.ToBits().ReshapeToUint64s()).ReshapeToUint16s().BitsToInt16()
	x38t1 := x38b0.InterleaveHi(zero.ToBits().ReshapeToUint64s()).ReshapeToUint16s().BitsToInt16()
	x38t2 := x38b1.InterleaveLo(zero.ToBits().ReshapeToUint64s()).ReshapeToUint16s().BitsToInt16()
	x38t3 := x38b1.InterleaveHi(zero.ToBits().ReshapeToUint64s()).ReshapeToUint16s().BitsToInt16()
	x38t4 := x38b2.InterleaveLo(zero.ToBits().ReshapeToUint64s()).ReshapeToUint16s().BitsToInt16()
	x38t5 := x38b2.InterleaveHi(zero.ToBits().ReshapeToUint64s()).ReshapeToUint16s().BitsToInt16()
	x38t6 := x38b3.InterleaveLo(zero.ToBits().ReshapeToUint64s()).ReshapeToUint16s().BitsToInt16()
	x38t7 := x38b3.InterleaveHi(zero.ToBits().ReshapeToUint64s()).ReshapeToUint16s().BitsToInt16()
	// Row strip 1: rows 8..15, coded columns 0..3.
	c39 := archsimd.LoadInt32x4Array((*[4]int32)(c[8:12])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64()
	c39 = c39.SetElem(1, archsimd.LoadInt32x4Array((*[4]int32)(c[12:16])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64().GetElem(0))
	c40 := c39.ToBits().ReshapeToUint16s().BitsToInt16()
	c41 := archsimd.LoadInt32x4Array((*[4]int32)(c[24:28])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64()
	c41 = c41.SetElem(1, archsimd.LoadInt32x4Array((*[4]int32)(c[28:32])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64().GetElem(0))
	c42 := c41.ToBits().ReshapeToUint16s().BitsToInt16()
	c43 := archsimd.LoadInt32x4Array((*[4]int32)(c[40:44])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64()
	c43 = c43.SetElem(1, archsimd.LoadInt32x4Array((*[4]int32)(c[44:48])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64().GetElem(0))
	c44 := c43.ToBits().ReshapeToUint16s().BitsToInt16()
	c45 := archsimd.LoadInt32x4Array((*[4]int32)(c[56:60])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64()
	c45 = c45.SetElem(1, archsimd.LoadInt32x4Array((*[4]int32)(c[60:64])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64().GetElem(0))
	c46 := c45.ToBits().ReshapeToUint16s().BitsToInt16()
	g47 := c40.Abs().ToBits()
	g47 = g47.AddSaturated(c42.Abs().ToBits())
	g47 = g47.AddSaturated(c44.Abs().ToBits())
	g47 = g47.AddSaturated(c46.Abs().ToBits())
	if g47.ReduceMax() > itx16ColumnL1Bound {
		return false
	}
	w49 := c40.ExtendLo4ToInt32()
	w50 := c40.HiToLo().ExtendLo4ToInt32()
	k51 := archsimd.LoadInt32x4Array(&t.p2896)
	r48l := w49.MulAdd(k51, bias)
	r48h := w50.MulAdd(k51, bias)
	w52 := c44.ExtendLo4ToInt32()
	w53 := c44.HiToLo().ExtendLo4ToInt32()
	k54 := archsimd.LoadInt32x4Array(&t.p2896)
	r48l = w52.MulAdd(k54, r48l)
	r48h = w53.MulAdd(k54, r48h)
	r48 := r48l.ToBits().ReshapeToUint16s().ConcatOdd(r48h.ToBits().ReshapeToUint16s()).BitsToInt16()
	k56 := archsimd.LoadInt32x4Array(&t.p2896)
	r55l := w49.MulAdd(k56, bias)
	r55h := w50.MulAdd(k56, bias)
	k57 := archsimd.LoadInt32x4Array(&t.n2896)
	r55l = w52.MulAdd(k57, r55l)
	r55h = w53.MulAdd(k57, r55h)
	r55 := r55l.ToBits().ReshapeToUint16s().ConcatOdd(r55h.ToBits().ReshapeToUint16s()).BitsToInt16()
	w59 := c42.ExtendLo4ToInt32()
	w60 := c42.HiToLo().ExtendLo4ToInt32()
	k61 := archsimd.LoadInt32x4Array(&t.p1567)
	r58l := w59.MulAdd(k61, bias)
	r58h := w60.MulAdd(k61, bias)
	w62 := c46.ExtendLo4ToInt32()
	w63 := c46.HiToLo().ExtendLo4ToInt32()
	k64 := archsimd.LoadInt32x4Array(&t.n3784)
	r58l = w62.MulAdd(k64, r58l)
	r58h = w63.MulAdd(k64, r58h)
	r58 := r58l.ToBits().ReshapeToUint16s().ConcatOdd(r58h.ToBits().ReshapeToUint16s()).BitsToInt16()
	k66 := archsimd.LoadInt32x4Array(&t.p3784)
	r65l := w59.MulAdd(k66, bias)
	r65h := w60.MulAdd(k66, bias)
	k67 := archsimd.LoadInt32x4Array(&t.p1567)
	r65l = w62.MulAdd(k67, r65l)
	r65h = w63.MulAdd(k67, r65h)
	r65 := r65l.ToBits().ReshapeToUint16s().ConcatOdd(r65h.ToBits().ReshapeToUint16s()).BitsToInt16()
	a68 := r48.AddSaturated(r65)
	a69 := r55.AddSaturated(r58)
	a70 := r55.SubSaturated(r58)
	a71 := r48.SubSaturated(r65)
	s72 := a68.Average(zero)
	s73 := a69.Average(zero)
	s74 := a70.Average(zero)
	s75 := a71.Average(zero)
	x76a0 := s72.InterleaveLo(s73).ToBits().ReshapeToUint32s()
	x76a1 := s72.InterleaveHi(s73).ToBits().ReshapeToUint32s()
	x76a2 := s74.InterleaveLo(s75).ToBits().ReshapeToUint32s()
	x76a3 := s74.InterleaveHi(s75).ToBits().ReshapeToUint32s()
	x76b0 := x76a0.InterleaveLo(x76a2).ReshapeToUint64s()
	x76b1 := x76a0.InterleaveHi(x76a2).ReshapeToUint64s()
	x76b2 := x76a1.InterleaveLo(x76a3).ReshapeToUint64s()
	x76b3 := x76a1.InterleaveHi(x76a3).ReshapeToUint64s()
	x76t0 := x76b0.InterleaveLo(zero.ToBits().ReshapeToUint64s()).ReshapeToUint16s().BitsToInt16()
	x76t1 := x76b0.InterleaveHi(zero.ToBits().ReshapeToUint64s()).ReshapeToUint16s().BitsToInt16()
	x76t2 := x76b1.InterleaveLo(zero.ToBits().ReshapeToUint64s()).ReshapeToUint16s().BitsToInt16()
	x76t3 := x76b1.InterleaveHi(zero.ToBits().ReshapeToUint64s()).ReshapeToUint16s().BitsToInt16()
