// itxGen16x4 runs the generated 16x4 kernel of type t and the network forms
// covering cols coded columns and rows coded rows; it reports false for a
// type without one and when a guard declines.
func itxGen16x4(c *[64]int32, d []byte, ds int, p []byte, ps int, t Type, cols, rows int) bool {
	switch t {
	case TypeDCTDCT:
		if cols <= 4 {
			return itxGen16x4DCTDCTC4R4(c, d, ds, p, ps)
		}
		return itxGen16x4DCTDCTC16R4(c, d, ds, p, ps)
	case TypeADSTDCT:
		return itxGen16x4ADSTDCTC16R4(c, d, ds, p, ps)
	case TypeDCTADST:
		return itxGen16x4DCTADSTC16R4(c, d, ds, p, ps)
	case TypeADSTADST:
		return itxGen16x4ADSTADSTC16R4(c, d, ds, p, ps)
	case TypeFlipADSTDCT:
		return itxGen16x4FlipDCTC16R4(c, d, ds, p, ps)
	case TypeDCTFlipADST:
		return itxGen16x4DCTFlipC16R4(c, d, ds, p, ps)
	case TypeFlipADSTFlipADST:
		return itxGen16x4FlipFlipC16R4(c, d, ds, p, ps)
	case TypeADSTFlipADST:
		return itxGen16x4ADSTFlipC16R4(c, d, ds, p, ps)
	case TypeFlipADSTADST:
		return itxGen16x4FlipADSTC16R4(c, d, ds, p, ps)
	case TypeVDCT:
		return itxGen16x4DCTIdenC16R4(c, d, ds, p, ps)
	case TypeHDCT:
		return itxGen16x4IdenDCTC16R4(c, d, ds, p, ps)
	}
	return false
}

