// itxGenHBDDCT8x8 runs the generated 10/12-bit 8x8 kernel of the network
// forms covering cols coded columns and rows coded rows (1..8 each).
func itxGenHBDDCT8x8(c *[64]int32, d []byte, ds int, p []byte, ps int, cols, rows int, mx int16) bool {
	switch {
	case cols <= 4:
		switch {
		case rows <= 4:
			return itxGenHBDDCT8x8C4R4(c, d, ds, p, ps, mx)
		default:
			return itxGenHBDDCT8x8C4R8(c, d, ds, p, ps, mx)
		}
	default:
		switch {
		case rows <= 4:
			return itxGenHBDDCT8x8C8R4(c, d, ds, p, ps, mx)
		default:
			return itxGenHBDDCT8x8C8R8(c, d, ds, p, ps, mx)
		}
	}
}

