	w44 := c4.HiToLo().ExtendLo4ToInt32()
	k45 := archsimd.LoadInt32x4Array(&t.p799)
	r42l := w43.MulAdd(k45, bias)
	r42h := w44.MulAdd(k45, bias)
	w46 := c16.ExtendLo4ToInt32()
	w47 := c16.HiToLo().ExtendLo4ToInt32()
	k48 := archsimd.LoadInt32x4Array(&t.n4017)
	r42l = w46.MulAdd(k48, r42l)
	r42h = w47.MulAdd(k48, r42h)
	r42 := r42l.ToBits().ReshapeToUint16s().ConcatOdd(r42h.ToBits().ReshapeToUint16s()).BitsToInt16()
	w50 := c12.ExtendLo4ToInt32()
	w51 := c12.HiToLo().ExtendLo4ToInt32()
	k52 := archsimd.LoadInt32x4Array(&t.p3406)
	r49l := w50.MulAdd(k52, bias)
	r49h := w51.MulAdd(k52, bias)
	w53 := c8.ExtendLo4ToInt32()
	w54 := c8.HiToLo().ExtendLo4ToInt32()
	k55 := archsimd.LoadInt32x4Array(&t.n2276)
	r49l = w53.MulAdd(k55, r49l)
	r49h = w54.MulAdd(k55, r49h)
	r49 := r49l.ToBits().ReshapeToUint16s().ConcatOdd(r49h.ToBits().ReshapeToUint16s()).BitsToInt16()
	k57 := archsimd.LoadInt32x4Array(&t.p2276)
