	a62 := r42.AddSaturated(r49)
	a63 := r42.SubSaturated(r49)
	a64 := r59.AddSaturated(r56)
	a65 := r59.SubSaturated(r56)
	w67 := a65.ExtendLo4ToInt32()
	w68 := a65.HiToLo().ExtendLo4ToInt32()
	k69 := archsimd.LoadInt32x4Array(&t.p2896)
	r66l := w67.MulAdd(k69, bias)
	r66h := w68.MulAdd(k69, bias)
	w70 := a63.ExtendLo4ToInt32()
