	s85 := a77.Average(zero)
	s86 := a78.Average(zero)
	s87 := a79.Average(zero)
	s88 := a80.Average(zero)
	s89 := a81.Average(zero)
	s90 := a82.Average(zero)
	s91 := a83.Average(zero)
