	s168 := a139.Shift(sh3).Average(zero)
	p169 := archsimd.LoadUint8x16Array(pw153).ReshapeToUint16s().BitsToInt16()
	p169.AddSaturated(s168).Max(zero).Min(mxv).ToBits().ReshapeToUint8s().StoreArray(dw152)
	s170 := a140.Shift(sh3).Average(zero)
