	c5 = c5.SetElem(1, archsimd.LoadInt32x4Array((*[4]int32)(c[20:24])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64().GetElem(0))
	c6 := c5.ToBits().ReshapeToUint16s().BitsToInt16()
	c7 := archsimd.LoadInt32x4Array((*[4]int32)(c[24:28])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64()
	c7 = c7.SetElem(1, archsimd.LoadInt32x4Array((*[4]int32)(c[28:32])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64().GetElem(0))
	c8 := c7.ToBits().ReshapeToUint16s().BitsToInt16()
