	c10 := c9.ToBits().ReshapeToUint16s().BitsToInt16()
	c11 := archsimd.LoadInt32x4Array((*[4]int32)(c[40:44])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64()
	c11 = c11.SetElem(1, archsimd.LoadInt32x4Array((*[4]int32)(c[44:48])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64().GetElem(0))
	c12 := c11.ToBits().ReshapeToUint16s().BitsToInt16()
	c13 := archsimd.LoadInt32x4Array((*[4]int32)(c[48:52])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64()
	c13 = c13.SetElem(1, archsimd.LoadInt32x4Array((*[4]int32)(c[52:56])).SaturateToInt16().ToBits().ReshapeToUint64s().BitsToFloat64().GetElem(0))
	c14 := c13.ToBits().ReshapeToUint16s().BitsToInt16()
