	r135h = w123.MulAdd(k137, r135h)
	r135 := r135l.ToBits().ReshapeToUint16s().ConcatOdd(r135h.ToBits().ReshapeToUint16s()).BitsToInt16()
	a138 := r118.AddSaturated(r125)
	a139 := r118.SubSaturated(r125)
	a140 := r135.AddSaturated(r132)
	a141 := r135.SubSaturated(r132)
	w143 := a141.ExtendLo4ToInt32()
