	r20l := w17.MulAdd(k21, bias)
	r20h := w18.MulAdd(k21, bias)
	r20 := r20l.ToBits().ReshapeToUint16s().ConcatOdd(r20h.ToBits().ReshapeToUint16s()).BitsToInt16()
	w23 := r20.ExtendLo4ToInt32()
	w24 := r20.HiToLo().ExtendLo4ToInt32()
	k25 := archsimd.LoadInt32x4Array(&t.p2896)
	r22l := w23.MulAdd(k25, bias)
	r22h := w24.MulAdd(k25, bias)
	w26 := r16.ExtendLo4ToInt32()
	w27 := r16.HiToLo().ExtendLo4ToInt32()
	k28 := archsimd.LoadInt32x4Array(&t.n2896)
	r22l = w26.MulAdd(k28, r22l)
	r22h = w27.MulAdd(k28, r22h)
	r22 := r22l.ToBits().ReshapeToUint16s().ConcatOdd(r22h.ToBits().ReshapeToUint16s()).BitsToInt16()
	k30 := archsimd.LoadInt32x4Array(&t.p2896)
	r29l := w23.MulAdd(k30, bias)
	r29h := w24.MulAdd(k30, bias)
	k31 := archsimd.LoadInt32x4Array(&t.p2896)
	r29l = w26.MulAdd(k31, r29l)
	r29h = w27.MulAdd(k31, r29h)
	r29 := r29l.ToBits().ReshapeToUint16s().ConcatOdd(r29h.ToBits().ReshapeToUint16s()).BitsToInt16()
	a32 := r10.AddSaturated(r20)
	a33 := r14.AddSaturated(r29)
	a34 := r14.AddSaturated(r22)
	a35 := r10.AddSaturated(r16)
	a36 := r10.SubSaturated(r16)
	a37 := r14.SubSaturated(r22)
	a38 := r14.SubSaturated(r29)
	a39 := r10.SubSaturated(r20)
	w41 := c4.ExtendLo4ToInt32()
