// itxGenHBDDCT32x32C8R8 is the 10/12-bit 32x32 DCT_DCT inverse transform and add for
// coefficients in the first 8 columns and 8 rows (column-major at stride
// 32); d/p hold the destination and prediction rows at strides ds/ps.
// Coefficient rows from rows on are zero: the row strips past them are
// skipped (tmp starts zero). It reports false, with dst untouched, when a
// guard declines or a stride exceeds itxGenMaxStride.
func itxGenHBDDCT32x32C8R8(c *[1024]int32, d []byte, ds int, p []byte, ps int, rows int, mx int16) bool {
	if uint(ds) > itxGenMaxStride || uint(ps) > itxGenMaxStride {
		return false
	}
	var tmp [256]int16
	var gc [4]archsimd.Uint16x8
	if !itxGenDCT32Row8((*[232]int32)(c[0:]), (*[256]int16)(tmp[0:]), &gc) {
		return false
	}
	m := gc[0].Max(gc[1]).Max(gc[2]).Max(gc[3])
	if m.ReduceMax() > itx16ColumnL1Bound {
		return false
	}
	itxGenHBDDCT32Col8((*[232]int16)(tmp[0:]), d, ds, p, ps, mx)
	itxGenHBDDCT32Col8((*[232]int16)(tmp[8:]), d[16:], ds, p[16:], ps, mx)
	itxGenHBDDCT32Col8((*[232]int16)(tmp[16:]), d[32:], ds, p[32:], ps, mx)
	itxGenHBDDCT32Col8((*[232]int16)(tmp[24:]), d[48:], ds, p[48:], ps, mx)
	return true
}

