// itxGenHBDDCT64x64C32R16 is the 10/12-bit 64x64 DCT_DCT inverse transform and add for
// coefficients in the first 32 columns and 16 rows (column-major at stride
// 32); d/p hold the destination and prediction rows at strides ds/ps.
// Coefficient rows from rows on are zero: the row strips past them are
// skipped (tmp starts zero). It reports false, with dst untouched, when a
// guard declines or a stride exceeds itxGenMaxStride.
func itxGenHBDDCT64x64C32R16(c *[1024]int32, d []byte, ds int, p []byte, ps int, rows int, mx int16) bool {
	if uint(ds) > itxGenMaxStride || uint(ps) > itxGenMaxStride {
		return false
	}
	var tmp [1024]int16
	var gc [8]archsimd.Uint16x8
	if !itxGenDCT64Row32((*[1000]int32)(c[0:]), (*[512]int16)(tmp[0:]), &gc) {
		return false
	}
	if rows > 8 && !itxGenDCT64Row32((*[1000]int32)(c[8:]), (*[512]int16)(tmp[512:]), &gc) {
		return false
	}
	m := gc[0].Max(gc[1]).Max(gc[2]).Max(gc[3]).Max(gc[4]).Max(gc[5]).Max(gc[6]).Max(gc[7])
	if m.ReduceMax() > itx16ColumnL1Bound {
		return false
	}
	itxGenHBDDCT64Col16((*[968]int16)(tmp[0:]), d, ds, p, ps, mx)
	itxGenHBDDCT64Col16((*[968]int16)(tmp[8:]), d[16:], ds, p[16:], ps, mx)
	itxGenHBDDCT64Col16((*[968]int16)(tmp[16:]), d[32:], ds, p[32:], ps, mx)
	itxGenHBDDCT64Col16((*[968]int16)(tmp[24:]), d[48:], ds, p[48:], ps, mx)
	itxGenHBDDCT64Col16((*[968]int16)(tmp[32:]), d[64:], ds, p[64:], ps, mx)
	itxGenHBDDCT64Col16((*[968]int16)(tmp[40:]), d[80:], ds, p[80:], ps, mx)
	itxGenHBDDCT64Col16((*[968]int16)(tmp[48:]), d[96:], ds, p[96:], ps, mx)
	itxGenHBDDCT64Col16((*[968]int16)(tmp[56:]), d[112:], ds, p[112:], ps, mx)
	return true
}

